## 2. PHP Authentication Check Script

```php
<?php
// access_control.php
session_start();

// Define allowed users (in production, use database)
$allowed_users = [
    'admin' => password_hash('securepass123', PASSWORD_DEFAULT),
    'user1' => password_hash('userpass456', PASSWORD_DEFAULT)
];

// Check if user is logged in
function is_authenticated() {
    return isset($_SESSION['authenticated']) && $_SESSION['authenticated'] === true;
}

// Authentication function
function authenticate($username, $password) {
    global $allowed_users;

    if (isset($allowed_users[$username])) {
        if (password_verify($password, $allowed_users[$username])) {
            $_SESSION['authenticated'] = true;
            $_SESSION['username'] = $username;
            return true;
        }
    }
    return false;
}

// IP blocking function
function is_ip_allowed($ip) {
    $blocked_ips = [
        '192.168.1.100',
        '10.0.0.5'
        // Add more IPs as needed
    ];

    return !in_array($ip, $blocked_ips);
}

// Time-based access control
function is_within_access_hours() {
    $current_hour = date('H');
    // Allow access only between 9 AM and 5 PM
    return ($current_hour >= 9 && $current_hour < 17);
}

// Main access check
function check_access() {
    $client_ip = $_SERVER['REMOTE_ADDR'];

    // Check IP
    if (!is_ip_allowed($client_ip)) {
        deny_access("Your IP address ($client_ip) has been blocked.");
    }

    // Check authentication
    if (!is_authenticated()) {
        header('Location: login.php');
        exit();
    }

    // Check time restrictions
    if (!is_within_access_hours()) {
        deny_access("Access is only available between 9:00 AM and 5:00 PM.");
    }

    return true;
}

